/**
 * Process weapon requests from the main thread.
 * Called every physics frame. Processes all queued requests.
 */
export function processWeaponRequest(): void;
/**
 * Fire a weapon directly from within the worker (for AI agents).
 * Bypasses the sharedWeapons buffer.
 *
 * @param {number} shooterIndex - Index of the shooter body
 * @param {string} shooterType - Type of shooter ('dynamic' or 'kinematic')
 * @param {Object} origin - Origin position { x, y, z }
 * @param {Object} direction - Direction { x, y, z }
 * @param {Object} [config] - Weapon configuration
 * @param {string} [config.weaponType='hitscan'] - Weapon type
 * @param {number} [config.damage=10] - Damage value
 * @param {number} [config.maxDistance=1000] - Max distance
 * @param {number} [config.speed=40] - Projectile speed
 * @param {number} [config.gravity=1] - Gravity multiplier
 * @param {number} [config.drag=0.01] - Drag coefficient
 * @param {number} [config.lifetime=5] - Projectile lifetime
 * @param {number} [config.aoeRadius=0] - AoE radius
 */
export function fireWeaponFromWorker(shooterIndex: number, shooterType: string, origin: any, direction: any, config?: {
    weaponType?: string;
    damage?: number;
    maxDistance?: number;
    speed?: number;
    gravity?: number;
    drag?: number;
    lifetime?: number;
    aoeRadius?: number;
}): void;
